import{_t as e,it as t,n,rt as r}from"./chunks/framework.Ke88N3OB.js";var i=JSON.parse(`{"title":"Agent tooling","description":"Agent guidance, skills, portable hooks and scoped check diagnostics","frontmatter":{"navigation":{"category":"Repository maintenance"},"title":"Agent tooling","description":"Agent guidance, skills, portable hooks and scoped check diagnostics","editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/docs/agent-tooling.md"},"headers":[],"relativePath":"guides/agent-tooling.md","filePath":"docs/agent-tooling.md","lastUpdated":1792509102000}`),a={name:`guides/agent-tooling.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="agent-tooling" tabindex="-1">Agent tooling <a class="header-anchor" href="#agent-tooling" aria-label="Permalink to “Agent tooling”">​</a></h1><p>Use this guide to run the repository&#39;s agent checks yourself or connect another agent client. The instructions, workflows and executable checks each have a home:</p><ul><li><a href="https://github.com/filiphsps/pumpkin-plugins/blob/master/AGENTS.md" target="_blank" rel="noreferrer">AGENTS.md</a> holds shared rules and points contributors to relevant guides and skills.</li><li><code>.agents/skills/</code> contains focused workflows. An agent can discover a skill or read its <code>SKILL.md</code> directly. Skills don&#39;t install hooks or authorize external actions.</li><li><code>.agents/hooks/</code> contains client-neutral Node scripts and client adapters. Codex registers <code>.agents/hooks/codex.mjs</code> in <code>.codex/hooks.json</code>; other clients need their own adapters.</li></ul><h2 id="run-checks-directly" tabindex="-1">Run checks directly <a class="header-anchor" href="#run-checks-directly" aria-label="Permalink to “Run checks directly”">​</a></h2><p>From the repository root, use the portable runner:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .agents/hooks/check.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --plan</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .agents/hooks/check.mjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .agents/hooks/check.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/upnpumpkin/src/plugin.ts</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint:actions</span></span></code></pre></div><p><code>--plan</code> prints the selected files and commands as JSON without running them. With no file paths, the runner collects all staged, unstaged and untracked paths from <code>git status</code>, including deletions and renames, then checks the applicable files and packages and adds repository-wide metadata checks. If you pass paths, it checks only those files and their packages; deleted paths are allowed, but repository-wide checks are skipped. Either mode checks generated READMEs when the selected changes include any non-generated files: only the affected plugins&#39; READMEs when nothing but plugin source changed, otherwise all of <code>pnpm readme:check</code>.</p><p>Checks don&#39;t apply fixes. If you need to fix lint issues, use the scoped <code>pnpm exec biome check --write</code> and <code>pnpm exec eslint --fix</code> commands on files you own.</p><table tabindex="0"><thead><tr><th>Change</th><th>Checks</th></tr></thead><tbody><tr><td>Existing files</td><td>Biome; TypeScript files also get the JSDoc lint</td></tr><tr><td>Lint configuration</td><td>Whole-repo lint, to catch newly invalid existing code</td></tr><tr><td>GitHub workflow or <code>.github/actionlint.yaml</code></td><td><code>pnpm run lint:actions</code></td></tr><tr><td>Package code</td><td>Typecheck and unit tests for that package and workspace dependents</td></tr><tr><td>Shared root build inputs or lockfile</td><td>Typecheck and unit tests for all packages</td></tr><tr><td>Deleted package</td><td>All package typechecks and unit tests, to catch remaining imports</td></tr><tr><td>Scripts, hook code, generators, <code>.github/</code>, <code>.codex/</code>, root <code>package.json</code> or <code>turbo.json</code>, release-please config</td><td><code>pnpm test:scripts</code></td></tr><tr><td>Only plugin source (no <code>package.json</code> or Markdown)</td><td>Generated READMEs of those plugins and their workspace dependents</td></tr><tr><td>Any other non-generated change</td><td><code>pnpm readme:check</code></td></tr><tr><td>No-path run with non-generated changes</td><td><code>pnpm check</code>, plus the applicable file and package checks</td></tr><tr><td>Only generated output</td><td>No checks</td></tr></tbody></table><p>Markdown-only package edits skip package tests. <code>tools/build/src/</code> is source code, not generated output. Real-server tests run separately because they need a server; see <a href="/pumpkin-plugins/guides/testing">Testing</a> and <a href="https://github.com/filiphsps/pumpkin-plugins/blob/master/.agents/skills/pumpkin-testing/SKILL.md" target="_blank" rel="noreferrer">the testing skill</a>.</p><h2 id="run-actionlint-locally" tabindex="-1">Run Actionlint locally <a class="header-anchor" href="#run-actionlint-locally" aria-label="Permalink to “Run Actionlint locally”">​</a></h2><p>The Actionlint workflow installs actionlint <code>1.7.12</code> and checks every workflow unless the only changed files are <code>.github/labels.yml</code> and/or <code>.coderabbit.yaml</code>. To run the same check locally, install that version using the <a href="https://github.com/rhysd/actionlint/blob/v1.7.12/docs/install.md" target="_blank" rel="noreferrer">upstream installation guide</a>. With Go installed, run:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> github.com/rhysd/actionlint/cmd/actionlint@v1.7.12</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint:actions</span></span></code></pre></div><p><code>.github/actionlint.yaml</code> registers the <code>ubuntu-26.04</code> runner label because actionlint doesn&#39;t include it in its built-in runner list.</p><h2 id="how-codex-scopes-automatic-checks" tabindex="-1">How Codex scopes automatic checks <a class="header-anchor" href="#how-codex-scopes-automatic-checks" aria-label="Permalink to “How Codex scopes automatic checks”">​</a></h2><p>When you run <code>check.mjs</code> without paths, Git status supplies the files to check. Codex&#39;s completion hooks use a narrower scope: around each tool call they compare only the paths it explicitly targets through <code>apply_patch</code> or a shell output redirection, and record the ones that changed. Codex sends every file edit as <code>apply_patch</code>; <code>Edit</code> and <code>Write</code> are only matcher aliases for it. A shell command that changes files as an implicit side effect has no attributable path. The root agent and each subagent also have separate scopes, so one agent&#39;s completion report doesn&#39;t include another agent&#39;s work.</p><p>Completion checks pass explicit paths, which means they skip repository-wide metadata checks. They still check generated READMEs when the scoped changes include non-generated files. Passing these fast checks doesn&#39;t prove runtime behavior, correct prose or the full CI workflow. See the <a href="https://learn.chatgpt.com/docs/hooks" target="_blank" rel="noreferrer">Codex Hooks guide</a> for the current trust flow and hook behavior: project hooks load only for trusted projects, and Codex requires review and trust for each non-managed hook definition before it runs.</p><p>The Codex adapter in <code>.agents/hooks/codex.mjs</code>, registered by <code>.codex/hooks.json</code>, sends <code>PreToolUse</code> shell and patch calls through the portable guard. <code>PostToolUse</code> records changed paths. <code>Stop</code> and <code>SubagentStop</code> check that agent&#39;s recorded paths and request one continuation when checks fail. The scope uses the Codex session ID and <code>turn_id</code>, with a separate identity for each subagent.</p><h2 id="portable-hook-protocol" tabindex="-1">Portable hook protocol <a class="header-anchor" href="#portable-hook-protocol" aria-label="Permalink to “Portable hook protocol”">​</a></h2><p>A client adapter can run <code>node .agents/hooks/run.mjs</code> with one JSON request on stdin. The runner writes one JSON response to stdout and exits with <code>0</code> for success or <code>1</code> for a refusal, failed check or invalid request. Resolve the script from the repository root; it runs checks there regardless of the caller&#39;s directory. A request&#39;s <code>cwd</code> only resolves relative file paths and defaults to the repository root.</p><table tabindex="0"><thead><tr><th>Event</th><th>Request fields</th><th>Response</th></tr></thead><tbody><tr><td><code>before-tool</code></td><td><code>tool</code>, <code>input</code>, optional <code>cwd</code></td><td><code>ok</code>, replacement <code>input</code> when allowed, or <code>reason</code> when refused</td></tr><tr><td><code>plan</code></td><td>Optional <code>files</code> array and <code>cwd</code></td><td><code>ok</code>, <code>files</code>, <code>steps</code>; runs no checks</td></tr><tr><td><code>check</code></td><td>Optional <code>files</code> array and <code>cwd</code></td><td><code>ok</code>, <code>files</code>, <code>failures</code>, readable <code>report</code></td></tr></tbody></table><p>For <code>plan</code> and <code>check</code>, explicit <code>files</code> keep file and package checks scoped to those paths. Generated READMEs are still checked when the selected files include a non-generated file. Omit <code>files</code> to discover all dirty files and include repository-wide metadata checks.</p><p>For example, this request previews checks for the hook runner without running them:</p><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;event&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;plan&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;files&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;.agents/hooks/run.mjs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }</span></span></code></pre></div><p>The adapter must map the client&#39;s tool names and payloads to the request fields the runner accepts:</p><table tabindex="0"><thead><tr><th>Tool type</th><th>Accepted names and inputs</th></tr></thead><tbody><tr><td>Shell</td><td><code>shell</code>, <code>bash</code> or <code>exec_command</code>; <code>input.command</code> or <code>input.cmd</code></td></tr><tr><td>Edit or write</td><td><code>edit</code> or <code>write</code>; <code>path</code> or <code>filePath</code>; <code>oldString</code> for edits or full <code>content</code> for writes</td></tr><tr><td>Patch</td><td><code>patch</code> or <code>apply_patch</code>; a string input or <code>patchText</code>, <code>patch</code> or <code>command</code> containing an apply-patch formatted patch</td></tr></tbody></table><p>Unknown tool names pass through; unsupported event names fail. The adapter should refuse an operation when <code>ok</code> is false and use a returned <code>input</code> when the runner rewrites one. At completion, invoke <code>check</code>. Feed a failure report back only if the client supports continuation, and cap retries to avoid loops. Make hook failures visible: malformed JSON, process errors and timeouts aren&#39;t successful checks. Keep client-specific API, hook trust, discovery locations and continuation formats in that client&#39;s adapter instead of adding them to the shared checks. For other clients, consult their hook documentation before writing an adapter.</p><h2 id="what-the-before-tool-guard-protects" tabindex="-1">What the before-tool guard protects <a class="header-anchor" href="#what-the-before-tool-guard-protects" aria-label="Permalink to “What the before-tool guard protects”">​</a></h2><p>The optional guard catches common use of other package managers and direct edits to <code>pnpm-lock.yaml</code>, Release Please changelogs and <code>.release-please-manifest.json</code>, build output, and generated Markdown blocks in READMEs and custom guides. It doesn&#39;t parse shell commands or provide a security boundary: shell matching is a heuristic, and shell-based file writes bypass the edit guard. Patches to a Markdown file containing generated blocks are refused as a whole because the guard can&#39;t reconstruct their hunks. Use a precise edit outside the generated block, or edit its source and regenerate the document. Before <code>pnpm install</code>, the shell and path guards still work, but an edit to an existing Markdown file is refused with a request to run <code>pnpm install</code>, since the block check needs workspace packages.</p><p>Plain Turbo runs receive <code>--output-logs=errors-only</code> unless they choose a log level or use shell syntax. Git authorization remains in <code>AGENTS.md</code>; the guard can&#39;t infer what the user authorized.</p><h2 id="verify-the-tooling" tabindex="-1">Verify the tooling <a class="header-anchor" href="#verify-the-tooling" aria-label="Permalink to “Verify the tooling”">​</a></h2><p>Run <code>pnpm test:scripts</code> to exercise scope selection, status parsing, guards and the JSON protocol. Before a large run, use <code>--plan</code> to confirm which packages the runner will select. To test a client integration, use a disposable checkout and check an allowed call, a refused call, a failing completion check, the retry limit and a clean completion. Unit tests of the shared protocol don&#39;t prove that a client loads its adapter.</p><p><code>pnpm check</code> also checks links, commands and repository paths in <code>AGENTS.md</code> and the skill documents, so those instructions don&#39;t silently drift away from the code they describe.</p>`,33)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};